const companies = $input.all();
const rssUrls = [];

for (const company of companies) {
  const website = company.json.website;
  const companyId = company.json.id;
  const companyName = company.json.name;

  // Common RSS feed patterns
  const feedPatterns = [
    `${website}/feed`,
    `${website}/rss`,
    `${website}/news/feed`,
    `${website}/press-releases/feed`,
    `${website}/blog/feed`
  ];

  for (const feedUrl of feedPatterns) {
    rssUrls.push({
      company_id: companyId,
      company_name: companyName,
      feed_url: feedUrl
    });
  }
}

return rssUrls.map(u => ({ json: u }));

const response = $input.first().json;
const companyId = $node['Generate RSS Feed URLs'].json.company_id;
const pressReleases = [];

try {
  const body = response.body || response;

  // Check if it's a valid RSS/XML feed
  if (typeof body === 'string' && (body.includes('<rss') || body.includes('<feed'))) {
    // Parse RSS feed (simplified - use rss-parser in production)
    const itemRegex = /<item[^>]*>(.*?)<\/item>/gs;
    const items = [...body.matchAll(itemRegex)];

    for (const item of items.slice(0, 10)) {
      const itemContent = item[1];

      const titleMatch = itemContent.match(/<title>(.*?)<\/title>/s);
      const linkMatch = itemContent.match(/<link>(.*?)<\/link>/s);
      const descMatch = itemContent.match(/<description>(.*?)<\/description>/s);
      const pubDateMatch = itemContent.match(/<pubDate>(.*?)<\/pubDate>/s);

      if (titleMatch && linkMatch) {
        pressReleases.push({
          company_id: companyId,
          title: titleMatch[1].replace(/<![CDATA[/g, '').replace(/]]>/g, '').trim(),
          url: linkMatch[1].trim(),
          content: descMatch ? descMatch[1].replace(/<![CDATA[/g, '').replace(/]]>/g, '').trim() : '',
          published_date: pubDateMatch ? new Date(pubDateMatch[1]).toISOString() : new Date().toISOString(),
          source: 'RSS',
          category: 'Press Release',
          raw_data: JSON.stringify({ item: itemContent.substring(0, 500) })
        });
      }
    }
  }
} catch (error) {
  // Silent fail for invalid/missing feeds
  console.log('Feed parse error (expected for some URLs):', error.message);
}

return pressReleases.map(p => ({ json: p }));
